import java.util.*;

class Solution {
  public long getMaxFunctionValue(List<Integer> receiver, long k) {
    int n = receiver.size();
    int log = 1;
    while ((1L << log) <= k) log++;
    int[][] jump = new int[log][n];
    long[][] sum = new long[log][n];
    for (int i = 0; i < n; i++) {
      jump[0][i] = receiver.get(i);
      sum[0][i] = receiver.get(i);
    }
    for (int p = 1; p < log; p++) {
      for (int i = 0; i < n; i++) {
        int middle = jump[p - 1][i];
        jump[p][i] = jump[p - 1][middle];
        sum[p][i] = sum[p - 1][i] + sum[p - 1][middle];
      }
    }
    long answer = 0;
    for (int start = 0; start < n; start++) {
      long total = start;
      int current = start;
      long steps = k;
      for (int p = 0; steps > 0; p++, steps >>= 1) {
        if ((steps & 1) != 0) {
          total += sum[p][current];
          current = jump[p][current];
        }
      }
      answer = Math.max(answer, total);
    }
    return answer;
  }
}
